// presti-demande-demo — les fenêtres du passage (brief : plans/011-cadrage-01-11/briefs/c4-n8n-demande-demo.md).
// Une demande est vue UNE fois : chaque passage couvre une fenêtre de 15 minutes alignée sur l'horloge, décalée de 5 minutes
// (le temps qu'une écriture soit visible). Les fenêtres se suivent sans trou ni chevauchement : [fin - 15 min, fin).
// La relance de J+2 couvre la même fenêtre, 48 heures plus tôt. Aucune mémoire dans n8n, aucune écriture en base.
const PAS = 15 * 60 * 1000;
const DECALAGE = 5 * 60 * 1000;
const J2 = 48 * 60 * 60 * 1000;
const brut = $input.first().json.timestamp;
const t = Date.parse(typeof brut === 'string' ? brut : '');
if (!Number.isFinite(t)) throw new Error('presti-demande-demo : heure du passage illisible');
const fin = Math.floor(t / PAS) * PAS - DECALAGE;
const debut = fin - PAS;
const iso = (ms) => new Date(ms).toISOString();
return [{ json: { avis_debut: iso(debut), avis_fin: iso(fin), relance_debut: iso(debut - J2), relance_fin: iso(fin - J2) } }];

// presti-demande-demo — les avis à Benj (brief : plans/011-cadrage-01-11/briefs/c4-n8n-demande-demo.md).
// Refait DANS LE CODE ce que la requête filtre (refus par défaut) : identifiant, taille et activité en liste fermée, date dans la
// fenêtre du passage, et pour la relance l'état « nouvelle ». Ne garde que l'identifiant, la taille, l'activité et les dates :
// jamais un prénom, une adresse ni un message, même si la lecture en rendait un. Un avis par demande, une relance par demande.
const TAILLES = ['1', '2 à 5', '6 à 20', 'plus de 20'];
const ACTIVITES = ['Artisan', 'Entreprise du bâtiment', 'Architecte', 'Autre'];
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const LIEN = 'https://qg.prestiapp.fr/controle?onglet=demos';
const f = $('Fenêtres du passage').first().json;
const dans = (iso, a, b) => { const x = Date.parse(iso); return typeof iso === 'string' && Number.isFinite(x) && x >= Date.parse(a) && x < Date.parse(b); };
const propre = (j) => (j && typeof j.id === 'string' && UUID.test(j.id) && TAILLES.includes(j.taille) && ACTIVITES.includes(j.activite)
  && typeof j.cree_le === 'string') ? { id: j.id, taille: j.taille, activite: j.activite, etat: j.etat, cree_le: j.cree_le } : null;
const equipe = (t) => (t === '1' ? 'seul' : t + ' personnes');
const avis = [];
const vus = new Set();
const ajouter = (type, d, texte) => {
  const cle = 'demo:' + d.id + ':' + type;
  if (vus.has(cle)) return;
  vus.add(cle);
  avis.push({ cle, type, demande_id: d.id, taille: d.taille, activite: d.activite, cree_le: d.cree_le, texte });
};
for (const it of $('Lire demandes neuves').all()) {
  const d = propre(it.json);
  if (!d || !dans(d.cree_le, f.avis_debut, f.avis_fin)) continue;
  ajouter('avis', d, 'Nouvelle demande de démo entreprise : ' + d.activite + ', équipe ' + equipe(d.taille) + '. À lire et traiter dans le Poste de contrôle : ' + LIEN);
}
for (const it of $('Lire demandes à relancer').all()) {
  const d = propre(it.json);
  if (!d || d.etat !== 'nouvelle' || !dans(d.cree_le, f.relance_debut, f.relance_fin)) continue;
  ajouter('relance_j2', d, 'Demande de démo entreprise toujours à traiter, reçue il y a 2 jours : ' + d.activite + ', équipe ' + equipe(d.taille) + '. Poste de contrôle : ' + LIEN);
}
return avis.map((a) => ({ json: a }));
